const { default: axios, isAxiosError } = require("axios");
const cheerio = require("cheerio");
const qs = require("qs");
const got = require("got");

function ttdl(url) {
  return new Promise(async (resolve, reject) => {
    const getDataInput = await axios.get("https://musicaldown.com/id");
    const $ = cheerio.load(getDataInput.data);
    let inputData = new Array();
    $('form')
      .find("input")
      .get()
      .map((map) => {
        inputData.push({
          name: $(map).attr("name"),
          value: $(map).attr("value"),
        });
      });
    const link = new URL(url);
    axios({
      method: "POST",
      url: "https://musicaldown.com/id/download",
      data: `${inputData[0]["name"]}=${encodeURIComponent(
        link["origin"] + link["pathname"]
      )}&${inputData[1]["name"]}=${inputData[1]["value"]}&${inputData[2]["name"]}=${inputData[2]["value"]}`,
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        "User-Agent":
          "Mozilla/5.0 (Linux; Android 9; CPH1923) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/93.0.4577.62 Mobile Safari/537.36",
        Accept:
          "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9",
        Origin: "https://musicaldown.com",
        Referer: "https://musicaldown.com/id",
        Cookie: getDataInput["headers"]["set-cookie"],
      },
    })
      .then((response) => {
        axios({
          method: "POST",
          url: "https://musicaldown.com/id/mp3",
          headers: {
            "User-Agent":
              "Mozilla/5.0 (Linux; Android 9; CPH1923) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/93.0.4577.62 Mobile Safari/537.36",
            Cookie: getDataInput["headers"]["set-cookie"],
          },
        })
          .then(({ data }) => {
            const $ = cheerio.load(response["data"]);
            const _ = cheerio.load(data);
            let video = new Array();
            let audio = new Array();
            let result = new Object();
            $('a[target=\'_blank\']')
              .get()
              .map((output) => {
                video.push($(output).attr("href"));
              });
            _("a.waves-effect")
              .get()
              .map((output) => {
                audio.push($(output).attr("href"));
              });
            result["title"] = $('title').text().trim();
            result["title_audio"] = _("title")
              .text()
              .split(" |")[0];
            result["thumbnail"] = $("img.responsive-img").attr("src");
            result["video"] = video.filter((output) =>
              output.includes("/video/")
            );
            result["audio"] = audio.filter((output) => {
              if (!/https:\/\//.test(output)) return;
              return output;
            });
            result['creator'] = '@TioXd';
            resolve(result);
          })
          .catch(reject);
      })
      .catch(reject);
  });
}

function igdl(url) {
  return new Promise(async (resolve) => {
    try {
      if (!url.match(/(?:https?:\/\/(web\.|www\.|m\.)?(facebook|fb)\.(com|watch)\S+)?$/) && !url.match(/(https|http):\/\/www.instagram.com\/(p|reel|tv|stories)/gi)) {
        return resolve({ developer: '@TioXd & Erlan', status: false, msg: `Link Url not valid` });
      }
      function decodeSnapApp(args) {
        let [h, u, n, t, e, r] = args;
        function decode(d, e, f) {
          const g = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ+/'.split('');
          let h = g.slice(0, e);
          let i = g.slice(0, f);
          let j = d.split('').reverse().reduce(function (a, b, c) {
            if (h.indexOf(b) !== -1)
              return a += h.indexOf(b) * (Math.pow(e, c));
          }, 0);
          let k = '';
          while (j > 0) {
            k = i[j % f] + k;
            j = (j - (j % f)) / f;
          }
          return k || '0';
        }
        r = '';
        for (let i = 0, len = h.length; i < len; i++) {
          let s = '';
          while (h[i] !== n[e]) {
            s += h[i];
            i++;
          }
          for (let j = 0; j < n.length; j++)
            s = s.replace(new RegExp(n[j], "g"), j.toString());
          r += String.fromCharCode(decode(s, e, 10) - t);
        }
        return decodeURIComponent(encodeURIComponent(r));
      }
      function getEncodedSnapApp(data) {
        return data.split('decodeURIComponent(escape(r))}(')[1]
          .split('))')[0]
          .split(',')
          .map(v => v.replace(/"/g, '').trim());
      }
      function getDecodedSnapSave(data) {
        return data.split('getElementById("download-section").innerHTML = "')[1]
          .split('"; document.getElementById("inputData").remove(); ')[0]
          .replace(/\\(\\)?/g, '');
      }
      function decryptSnapSave(data) {
        return getDecodedSnapSave(decodeSnapApp(getEncodedSnapApp(data)));
      }
      const html = await got.post('https://snapsave.app/action.php?lang=id', {
        headers: {
          'accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9',
          'content-type': 'application/x-www-form-urlencoded',
          'origin': 'https://snapsave.app',
          'referer': 'https://snapsave.app/id',
          'user-agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/103.0.0.0 Safari/537.36'
        },
        form: { url }
      }).text();
      const decode = decryptSnapSave(html);
      const $ = cheerio.load(decode);
      const results = [];
      if ($('table.table').length || $('article.media > figure').length) {
        const thumbnail = $('article.media > figure').find('img').attr('src');
        $('tbody > tr').each((_, el) => {
          const $el = $(el);
          const $td = $el.find('td');
          const resolution = $td.eq(0).text();
          let url = $td.eq(2).find('a').attr('href') || $td.eq(2).find('button').attr('onclick');
          const shouldRender = /get_progressApi/ig.test(url || '');
          if (shouldRender) {
            url = /get_progressApi\('(.*?)'\)/.exec(url || '')?.[1] || url;
          }
          results.push({
            resolution,
            thumbnail,
             url,
            shouldRender
          });
        });        
      } else {
        $('div.download-items__thumb').each((_, tod) => {
          const thumbnail = $(tod).find('img').attr('src');
          $('div.download-items__btn').each((_, ol) => {
            let url = $(ol).find('a').attr('href');
            if (!/https?:\/\//.test(url || '')) {
              url = `https://snapsave.app${url}`;
            }
            results.push({
              wm: '@TioXd & Erlan',
              thumbnail,
              url
            });
          });
        });
      }
      if (!results.length) {
        return resolve('Result Not Found! Check Your Url Now!');
      }
      return resolve(results);
    } catch (e) {
      return resolve('Request Failed With Code 401');
    }
  });
}

